const output = ($json.output ?? '').trim();

const isInsert = output.toUpperCase().startsWith('INSERT');
const isUpdate = output.toUpperCase().startsWith('UPDATE');

if (!isInsert && !isUpdate) {
  throw new Error('Output bukan SQL valid: ' + output.substring(0, 150));
}

// Hapus markdown jika ada
const clean = output
  .replace(/```sql/gi, '')
  .replace(/```/g, '')
  .trim();

return [{ json: { output: clean } }];
